// Desktop home, using the blog data generated by Astro.
const {posts,projects,total}=window.BLOG;
const world=document.getElementById('world');
const icons={file:'<path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h4M9 12h6M9 16h6"/>',folder:'<path d="M3 7V5h7l2 3h9v12H3z"/><path d="M3 9h18"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 18"/>',person:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',terminal:'<path d="m4 6 5 5-5 5m8 1h8"/>',book:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-2-1-6-2-10 1Z"/>',rss:'<path d="M4 4a16 16 0 0 1 16 16M4 10a10 10 0 0 1 10 10"/><circle cx="5" cy="19" r="1"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let variant='B',selected=0,section='featured',query='',expanded=false,layer=10;
const names={A:'复古未来桌面',B:'经典 Mac 桌面',C:'个人工作台'};
const clock=()=>new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
const lights='<span class="lights" aria-hidden="true"><span></span><span></span><span></span></span>';
const topbar=(brand)=>`<header class="topbar"><div class="left"><span class="brand-icon">✳</span><strong>${brand}</strong><button data-action="writing">文章</button><button data-action="projects">项目</button><button class="optional" data-action="about">关于</button></div><div class="right"><span class="optional">⌁ &nbsp; ▰</span><time class="clock">${clock()}</time></div></header>`;
const dock=()=>`<nav class="dock" aria-label="桌面应用"><button class="blue" data-action="writing" aria-label="文章">${icon('folder')}</button><button class="orange" data-action="projects" aria-label="项目">${icon('code')}</button><button class="dark" data-action="terminal" aria-label="关于 Geo">${icon('terminal')}</button><button class="green" data-action="search" aria-label="搜索文章">${icon('search')}</button><button class="cream" data-action="about" aria-label="个人介绍">${icon('person')}</button></nav>`;
const desktopFiles=()=>`<nav class="desktop-files" aria-label="桌面文件"><button class="desktop-file" data-action="writing"><span class="file-icon">${icon('folder')}</span>随手记下的事</button><button class="desktop-file" data-action="projects"><span class="file-icon">${icon('code')}</span>我的小工具</button><button class="desktop-file" data-post="0"><span class="file-icon">${icon('file')}</span>写给三十岁的我</button><button class="desktop-file" data-action="about"><span class="file-icon">${icon('person')}</span>关于 Geo</button></nav>`;
const postRows=(count=4)=>posts.slice(0,count).map((p,i)=>`<button class="post-row" data-post="${i}"><span class="index">${String(i+1).padStart(2,'0')}</span><span class="post-title">${esc(p.title)}</span><time>${p.date}</time><span class="arrow">↗</span></button>`).join('');
const bar=(title,draggable=false)=>`<div class="window-bar">${lights}<button class="handle" ${draggable?'data-drag aria-label="移动窗口，可用方向键"':''}>${title}</button>${draggable?'<button class="window-action" data-center aria-label="窗口居中">⊙</button>':''}</div>`;
function sidebar(){return `<aside class="finder-sidebar"><p>个人收藏</p><button data-section="all" class="${section==='all'?'active':''}">${icon('folder')}所有文章</button><button data-section="life" class="${section==='life'?'active':''}">${icon('book')}生活与思考</button><button data-section="tech" class="${section==='tech'?'active':''}">${icon('terminal')}AI 与编程</button><p style="margin-top:20px">工作空间</p><button data-section="projects" class="${section==='projects'?'active':''}">${icon('code')}我的项目</button><button data-action="about">${icon('person')}关于 Geo</button><div class="bottom-note">一个人的小宇宙。<br>慢慢写，慢慢做。</div></aside>`;}
function filteredPosts(){return posts.map((p,i)=>({...p,i})).filter(p=>{const life=/summary|life|生活|三十|30 年/i.test(p.tags.join(' ')+p.title);return (section==='all'||section==='featured'&&p.featured||section==='life'&&life||section==='tech'&&!life)&&(!query||(p.title+p.description+p.tags.join(' ')).toLowerCase().includes(query.toLowerCase()));});}
function preview(p){return `<div class="preview-paper" aria-hidden="true">${icon('file')}<div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div></div><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p><button class="read-button" data-post="${selected}">打开阅读 ↗</button>`;}
function projectTiles(){return projects.map(p=>`<a class="project-tile" href="${p.url}" target="_blank" rel="noopener"><img src="${p.image}" alt="${esc(p.title)} 项目封面"><div><h3>${esc(p.title)} ↗</h3><p>${esc(p.summary)}</p></div></a>`).join('');}
function finderContent(){if(variant==='B')return nativeFinderContent();if(section==='projects')return `${sidebar()}<div class="finder-projects">${projectTiles()}</div>`;const found=filteredPosts();if(found.length&&!found.some(p=>p.i===selected))selected=found[0].i;return `${sidebar()}<section class="finder-list"><div class="finder-list-head"><span>名称</span><span>修改日期</span></div>${found.length?found.map(p=>`<button class="finder-row ${selected===p.i?'selected':''}" data-select="${p.i}" aria-pressed="${selected===p.i}">${icon('file')}<span class="file-name"><strong>${esc(p.title)}</strong><small>${p.date}</small></span><span class="file-type">MD</span></button>`).join(''):'<p class="empty">没有找到这篇文章，换个词试试。</p>'}</section><aside class="finder-preview">${found.length?preview(posts[selected]):'<p>试试搜索 “Pi” 或 “Python”。</p>'}</aside>`;}
const nativeImg=(name,alt='')=>`<img class="native-icon" src="/desktop/assets/macos/${name}.png" alt="${alt}">`;
const traffic=(id)=>`<div class="traffic"><button data-window-close="${id}" aria-label="关闭窗口"><span>×</span></button><button data-window-min="${id}" aria-label="最小化窗口"><span>−</span></button><button data-window-max="${id}" aria-label="最大化窗口"><span>↗</span></button></div>`;
const finderNames={featured:'Featured',all:'全部文章',life:'生活与思考',tech:'AI 与编程',projects:'Projects'};
let projectSelected=0;let finderHistory=['featured'],finderCursor=0;
function navigateFinder(next){if(section!==next){finderHistory=finderHistory.slice(0,finderCursor+1);finderHistory.push(next);finderCursor++;}section=next;query='';updateFinder();}
function nativeSidebar(){return `<aside class="finder-sidebar"><p>个人收藏</p>${[['featured','book','Featured'],['all','file','全部文章'],['projects','folder','Projects']].map(([key,glyph,label])=>`<button data-section="${key}" class="${section===key?'active':''}">${icon(glyph)}${label}${key==='all'?`<small>${total}</small>`:''}</button>`).join('')}<p class="sidebar-label">分类</p>${[['life','book','生活与思考'],['tech','terminal','AI 与编程']].map(([key,glyph,label])=>`<button data-section="${key}" class="${section===key?'active':''}">${icon(glyph)}${label}</button>`).join('')}<p class="sidebar-label">位置</p><button data-action="about">${icon('person')}Geo 的 Mac</button><a class="sidebar-link" href="https://github.com/geoqiao" target="_blank" rel="noopener">${icon('code')}GitHub</a></aside>`;}
function nativeFinderContent(){const projectMode=section==='projects';let found=projectMode?projects.map((p,i)=>({...p,i})).filter(p=>(p.title+p.summary).toLowerCase().includes(query.toLowerCase())):filteredPosts();if(section==='featured')found.sort((a,b)=>window.BLOG.featured.indexOf(a.issueNumber)-window.BLOG.featured.indexOf(b.issueNumber));if(found.length&&!found.some(p=>p.i===(projectMode?projectSelected:selected))){if(projectMode)projectSelected=found[0].i;else selected=found[0].i;}const active=projectMode?projectSelected:selected;const p=found.find(p=>p.i===active);return `${nativeSidebar()}<section class="finder-list" aria-label="${finderNames[section]}"><div class="finder-list-head"><span>名称</span><span>${projectMode?'种类':'修改日期'}</span></div>${found.map(p=>`<button class="finder-row ${active===p.i?'selected':''}" ${projectMode?'data-project-select':'data-select'}="${p.i}" aria-pressed="${active===p.i}">${nativeImg(projectMode?'folder':'document')}<span class="file-name"><strong>${esc(p.title)}${projectMode?'':'.md'}</strong></span><time>${projectMode?'项目':p.date}</time></button>`).join('')||'<p class="empty">没有找到匹配的项目。</p>'}</section><aside class="finder-preview">${p?`${projectMode?`<img class="project-preview-image" src="${p.image}" alt="${esc(p.title)} 项目预览">`:`<div class="quicklook-paper"><span class="quicklook-label">GEO QIAO / NOTES</span><h4>${esc(p.title)}</h4><p>${esc(p.description)}</p><div class="paper-lines"></div></div>`}<h2>${esc(p.title)}</h2><p class="file-info">${projectMode?'项目文件夹':'Markdown 文稿'}</p>${projectMode?`<p class="project-description">${esc(p.summary)}</p><a class="read-button" href="${p.url}" target="_blank" rel="noopener">打开项目 ↗</a>`:`<dl><dt>创建日期</dt><dd>${p.date}</dd><dt>标签</dt><dd>${esc(p.tags.join('、'))}</dd></dl><button class="read-button" data-post="${p.i}">打开阅读</button>`}`:''}</aside>`;}
function mac(){return `<main class="mac mac-native"><header class="system-menu"><div class="system-menu-left"><button class="apple-menu" data-mac-menu="apple" aria-label="Apple 菜单"></button><button class="app-menu" data-mac-menu="finder"><strong>访达</strong></button><button data-mac-menu="file">文件</button><button data-mac-menu="edit">编辑</button><button data-mac-menu="view">显示</button><button data-mac-menu="go">前往</button><button data-mac-menu="window">窗口</button><button data-mac-menu="help">帮助</button></div><div class="system-menu-right"><span class="menu-wifi"><svg viewBox="0 0 24 24"><path d="M2 8a16 16 0 0 1 20 0M5 12a10 10 0 0 1 14 0M8 16a5 5 0 0 1 8 0"/><circle cx="12" cy="20" r="1"/></svg></span><select class="theme-picker" aria-label="桌面外观主题"><option value="system">自动</option><option value="light">Light</option><option value="dark">Dark</option></select><span class="battery">▰</span><button data-action="search" aria-label="聚焦搜索">${icon('search')}</button><button data-native-open="preferences" aria-label="控制中心"><svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="6" rx="3"/><circle cx="7" cy="7" r="1"/><rect x="3" y="14" width="18" height="6" rx="3"/><circle cx="17" cy="17" r="1"/></svg></button><time class="clock">${clock()}</time></div></header>
<nav class="native-desktop" aria-label="桌面文件"><button data-action="writing">${nativeImg('folder')}<span>我的文章</span></button><button data-action="projects">${nativeImg('folder')}<span>Side Projects</span></button><button data-post="0">${nativeImg('document')}<span>写给三十岁的我.md</span></button><button data-action="about"><img class="desktop-avatar" src="/desktop/assets/avatar.png" alt=""><span>关于 Geo.png</span></button></nav>
<section id="native-terminal" class="window native-terminal" aria-label="终端"><header class="native-titlebar">${traffic('native-terminal')}<button class="handle" data-drag aria-label="移动终端，可用方向键">geo — zsh — 80×24</button><button data-center class="native-center" aria-label="居中终端">⊙</button></header><div class="native-terminal-body"><p class="terminal-last">Last login: ${new Date().toDateString()} on ttys001</p><p><b>geo@MacBook-Pro</b> ~ % whoami</p><pre>G E O  /  P E R S O N A L  S P A C E

  writing    → Documents/
  building   → Projects/
  wondering  → everywhere</pre><p>金融行业的贷后策略分析师。<br>写代码，做工具，记下生活。</p><form id="native-terminal-form"><label><b>geo@MacBook-Pro</b> ~ % <input id="terminal-input" aria-label="终端命令，输入 help 查看可用命令" placeholder="help" autocomplete="off" spellcheck="false"></label></form><div id="terminal-output"></div></div></section>
<section id="native-note" class="window native-note" aria-label="备忘录"><header class="native-titlebar">${traffic('native-note')}<button class="handle" data-drag aria-label="移动备忘录，可用方向键">备忘录</button><button data-center class="native-center" aria-label="居中备忘录">⊙</button></header><div class="note-toolbar">${icon('book')}<span>▧</span><span>☑</span><span>Aa</span><span>↗</span></div><div class="native-note-body"><time>2026年11月15日 10:00</time><h2>嘿，欢迎来我电脑上坐坐 👋</h2><p>这里是 Geo 的个人空间。</p><p>左边的文稿里，有我写下的生活、AI 工作流和编程实践。</p><p>也可以打开 Safari，看看那些折腾出来的小项目。</p><div class="note-check"><span>✓</span> 保持好奇</div><div class="note-check"><span>✓</span> 动手做点东西</div><p class="note-sign">— Geo</p></div></section>
<section id="native-finder" class="window finder native-finder gallery-view" aria-label="访达"><header class="native-finder-toolbar">${traffic('native-finder')}<div class="finder-navigation"><button data-finder-back aria-label="后退" disabled>‹</button><button data-finder-forward aria-label="前进" disabled>›</button></div><button class="handle" data-drag aria-label="移动访达，可用方向键"><span id="finder-location">${finderNames[section]} — Geo</span></button><div class="finder-tools"><button data-view="list" aria-label="列表视图" aria-pressed="false">☷</button><button data-view="gallery" aria-label="图标视图" aria-pressed="true">▦</button><span class="tool-separator"></span><button data-action="about" aria-label="文件信息">ⓘ</button><button data-center class="native-center" aria-label="居中访达">⊙</button></div><input class="search" id="finder-search" type="search" placeholder="搜索" aria-label="搜索文稿" value="${esc(query)}"></header><div class="finder-body">${finderContent()}</div><footer><span>${nativeImg('folder')} Geo Qiao <span class="path-chevron">›</span> 文稿 <span class="path-chevron">›</span> 所有文章</span><span>${filteredPosts().length} 个项目</span></footer></section>
<section id="native-safari" class="window native-safari" aria-label="Safari 项目浏览器" hidden><header class="native-titlebar">${traffic('native-safari')}<button class="handle" data-drag aria-label="移动 Safari，可用方向键">‹ &nbsp; ›</button><div class="safari-address">♧ &nbsp; geoqiao.me/projects</div><button data-center class="native-center" aria-label="居中浏览器">⊙</button></header><div class="safari-content"><p class="eyebrow">GEO QIAO / SIDE PROJECTS</p><h2>Small tools.<br>Real things.</h2><div class="project-grid">${projectTiles()}</div></div></section>
<section id="native-preferences" class="window native-preferences" aria-label="桌面设置" hidden><header class="native-titlebar">${traffic('native-preferences')}<button class="handle" data-drag aria-label="移动设置，可用方向键">桌面与外观</button><button data-center class="native-center" aria-label="居中设置">⊙</button></header><div class="preferences-body">${nativeImg('settings')}<h2>选择你的桌面</h2><button data-wallpaper="day" class="wallpaper-swatch day">明亮</button><button data-wallpaper="night" class="wallpaper-swatch night">夜色</button><p>窗口位置可拖动，绿灯切换最大化。</p><button class="read-button" data-reset-desktop>整理桌面</button></div></section>
<section id="native-trash" class="window native-trash" aria-label="废纸篓" hidden><header class="native-titlebar">${traffic('native-trash')}<button class="handle" data-drag aria-label="移动废纸篓，可用方向键">废纸篓</button><button data-center class="native-center" aria-label="居中废纸篓">⊙</button></header><div class="trash-body">${nativeImg('trash')}<h2>废纸篓是空的</h2><p>想法都值得先留下来。</p></div></section>
<nav class="native-dock" aria-label="Dock">${[['finder','writing','访达'],['safari','projects','Safari · 项目'],['notes','note','备忘录'],['terminal','terminal','终端'],['contacts','about','关于 Geo'],['settings','preferences','系统设置']].map(([name,action,label])=>`<button data-native-app="${action}" aria-label="${label}" class="${['finder','notes','terminal'].includes(name)?'running':''}">${nativeImg(name)}<span class="dock-tooltip">${label}</span><i></i></button>`).join('')}<span class="dock-separator"></span><button data-native-app="trash" aria-label="废纸篓">${nativeImg('trash')}<span class="dock-tooltip">废纸篓</span><i></i></button></nav><div id="native-menu" class="native-menu" hidden></div></main>`;}
function render(){document.body.dataset.variant='B';world.innerHTML=mac();setupDrag();updateFinder();window.syncAppearance?.();window.mountDesktopApps?.();}
function switchVariant(key){variant=key;section=key==='B'?'featured':'all';query='';selected=0;expanded=false;const url=new URL(location.href);url.searchParams.set('variant',key);history.replaceState(null,'',url);render();window.scrollTo(0,0);}
const reader=document.getElementById('reader');
function openPost(i){window.openArticle(i);}
function showProjects(){if(variant==='B'){section='projects';query='';openNative('finder');updateFinder();return;}if(variant==='C'){document.querySelector('.project-shelf').scrollIntoView({behavior:'smooth',block:'center'});return;}document.querySelector('.project-overlay')?.remove();const panel=document.createElement('section');panel.className='window project-overlay';panel.setAttribute('aria-label','我的项目');panel.innerHTML=`<div class="window-bar">${lights}<span class="handle">projects / 小工具实验室</span><button data-close-projects aria-label="关闭项目窗口">×</button></div><div class="project-grid">${projectTiles()}</div>`;world.append(panel);panel.querySelector('[data-close-projects]').focus();}
function updateFinder(){document.querySelector('.finder-body').innerHTML=finderContent();if(variant==='B'){document.querySelector('[data-finder-back]').disabled=finderCursor===0;document.querySelector('[data-finder-forward]').disabled=finderCursor===finderHistory.length-1;document.getElementById('finder-location').textContent=finderNames[section]+' — Geo';document.getElementById('finder-search').value=query;}const count=section==='projects'?projects.filter(p=>(p.title+p.summary).toLowerCase().includes(query.toLowerCase())).length:filteredPosts().length;document.querySelector('.finder footer').innerHTML=`<span>${variant==='B'?nativeImg('folder'):''} Geo Qiao <span class="path-chevron">›</span> ${finderNames[section]||'文章'}</span><span>${count} 个项目</span>`;}
function allWriting(){if(variant==='B'){openNative('finder');section='all';query='';updateFinder();return;}expanded=!expanded;const host=document.getElementById(variant==='A'?'orbit-posts':'desk-posts');host.innerHTML=postRows(expanded?12:variant==='A'?4:5);if(variant==='A'&&expanded){document.querySelector('.orbit-notes').style.maxHeight='400px';host.style.maxHeight='300px';host.style.overflow='auto';}host.scrollIntoView({behavior:'smooth',block:'center'});}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.post!==undefined){openPost(Number(button.dataset.post));return;}if(button.dataset.projectSelect!==undefined){projectSelected=Number(button.dataset.projectSelect);updateFinder();return;}if(button.dataset.select!==undefined){selected=Number(button.dataset.select);if(innerWidth<=760||event.detail===0||event.detail>1){openPost(selected);}else{document.querySelectorAll('[data-select]').forEach(row=>{const yes=Number(row.dataset.select)===selected;row.classList.toggle('selected',yes);row.setAttribute('aria-pressed',String(yes));});const previewHost=document.createElement('div');previewHost.innerHTML=nativeFinderContent();document.querySelector('.finder-preview').innerHTML=previewHost.querySelector('.finder-preview').innerHTML;}return;}if(button.dataset.section){navigateFinder(button.dataset.section);return;}if(button.hasAttribute('data-close')){button.closest('dialog').close();return;}if(button.hasAttribute('data-close-projects')){button.closest('.project-overlay').remove();return;}if(button.id.startsWith('variant-')){switchVariant(button.id.slice(-1));return;}if(button.id==='next'||button.id==='previous'){cycle(button.id==='next'?1:-1);return;}switch(button.dataset.action){case 'about':document.getElementById('about').showModal();break;case 'terminal':if(variant==='B')openNative('terminal');else document.getElementById('about').showModal();break;case 'projects':showProjects();break;case 'writing':case 'all':allWriting();break;case 'search':if(variant!=='B')switchVariant('B');openNative('finder');document.getElementById('finder-search').focus();break;}});
document.addEventListener('dblclick',event=>{const project=event.target.closest('[data-project-select]');if(project)window.open(projects[Number(project.dataset.projectSelect)].url,'_blank','noopener');});
document.addEventListener('input',event=>{if(event.target.id==='finder-search'){query=event.target.value;updateFinder();}if(event.target.id==='desk-search'){const text=event.target.value.toLowerCase();document.getElementById('desk-posts').innerHTML=posts.map((p,i)=>({...p,i})).filter(p=>(p.title+p.description).toLowerCase().includes(text)).map(p=>`<button class="post-row" data-post="${p.i}"><span class="index">✎</span><span class="post-title">${esc(p.title)}</span><span class="arrow">↗</span></button>`).join('')||'<p class="empty">这页还没写到，试试别的关键词。</p>';}});
function cycle(offset){const keys=['A','B','C'];switchVariant(keys[(keys.indexOf(variant)+offset+3)%3]);}
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelector('.project-overlay')?.remove();const menu=document.getElementById('native-menu');if(menu)menu.hidden=true;}if(event.target.closest('input,textarea,[contenteditable],button[data-drag]')||document.querySelector('dialog[open]'))return;});
for(const dialog of document.querySelectorAll('dialog')){let outside=false;const isOutside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;};dialog.addEventListener('pointerdown',e=>outside=isOutside(e));dialog.addEventListener('pointerup',e=>{if(dialog.id!=='reader'&&outside&&isOutside(e))dialog.close();outside=false;});}
function setupDrag(){for(const handle of world.querySelectorAll('[data-drag]')){if(handle.dataset.dragReady)continue;handle.dataset.dragReady='true';const panel=handle.closest('.window');panel.addEventListener('pointerdown',()=>raiseWindow(panel));let dx=0,dy=0;const move=(x,y)=>{panel.style.position='fixed';panel.style.transform='none';panel.style.left=Math.max(0,Math.min(x,innerWidth-panel.offsetWidth))+'px';panel.style.top=Math.max(37,Math.min(y,innerHeight-95-Math.min(panel.offsetHeight,innerHeight-132)))+'px';panel.style.right='auto';raiseWindow(panel);};handle.addEventListener('pointerdown',e=>{if(e.button!==0||innerWidth<=760||panel.classList.contains('maximized'))return;const r=panel.getBoundingClientRect();dx=e.clientX-r.left;dy=e.clientY-r.top;handle.setPointerCapture(e.pointerId);});handle.addEventListener('pointermove',e=>{if(handle.hasPointerCapture(e.pointerId))move(e.clientX-dx,e.clientY-dy);});handle.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||innerWidth<=760)return;e.preventDefault();const r=panel.getBoundingClientRect();move(r.left+(e.key==='ArrowRight'?15:e.key==='ArrowLeft'?-15:0),r.top+(e.key==='ArrowDown'?15:e.key==='ArrowUp'?-15:0));});panel.querySelector('[data-center]')?.addEventListener('click',()=>{if(innerWidth<=760)return;move((innerWidth-panel.offsetWidth)/2,(innerHeight-panel.offsetHeight)/2);document.getElementById('announce').textContent='窗口已居中';});handle.addEventListener('lostpointercapture',()=>document.getElementById('announce').textContent='窗口位置已更新');}}
window.addEventListener('resize',()=>{for(const p of document.querySelectorAll('.window[style]')){p.style.position='';p.style.left='';p.style.top='';p.style.right='';p.style.transform='';}});
variant='B';render();setInterval(()=>document.querySelectorAll('.clock').forEach(e=>e.textContent=clock()),30000);

function raiseWindow(panel){const windows=[...world.querySelectorAll('.window')].filter(p=>p!==panel).sort((a,b)=>Number(getComputedStyle(a).zIndex)-Number(getComputedStyle(b).zIndex));windows.push(panel);windows.forEach((p,i)=>p.style.zIndex=String(10+i));}
function openNative(name){if(innerWidth<=760){document.querySelectorAll('.mac-native .window').forEach(w=>w.classList.toggle('mobile-inactive',w.id!=='native-'+name));}const panel=document.getElementById('native-'+name);if(!panel)return;panel.hidden=false;panel.classList.add("is-open");raiseWindow(panel);if(innerWidth<=760)requestAnimationFrame(()=>panel.scrollIntoView({block:"start"}));document.querySelector(`[data-native-app="${{finder:'writing',safari:'projects'}[name]||name}"]`)?.classList.add('running');}
document.addEventListener('click',event=>{if(variant!=='B')return;const button=event.target.closest('button');if(!button){if(!event.target.closest('.native-menu'))document.getElementById('native-menu').hidden=true;return;}
if(button.dataset.nativeApp){const action=button.dataset.nativeApp;if(action==='about'){document.getElementById('about').showModal();return;}openNative({writing:'finder',projects:'safari',note:'note'}[action]||action);}
if(button.hasAttribute('data-finder-back')||button.hasAttribute('data-finder-forward')){finderCursor+=button.hasAttribute('data-finder-back')?-1:1;section=finderHistory[finderCursor];query='';updateFinder();}
if(button.dataset.nativeOpen)openNative(button.dataset.nativeOpen);
const id=button.dataset.windowClose||button.dataset.windowMin||button.dataset.windowMax;
if(id){const panel=document.getElementById(id);if(button.dataset.windowMax){panel.classList.toggle('maximized');raiseWindow(panel);}else{panel.hidden=true;if(innerWidth<=760){openNative('finder');window.scrollTo({top:0});}if(button.dataset.windowClose)document.querySelector(`[data-native-app="${{finder:'writing',safari:'projects',note:'note'}[id.replace('native-','')]||id.replace('native-','')}"]`)?.classList.remove('running');}}
if(button.dataset.view){document.querySelector('.native-finder').classList.toggle('gallery-view',button.dataset.view==='gallery');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}
if(button.dataset.wallpaper)window.setAppearance(button.dataset.wallpaper==='night'?'dark':'light');
if(button.dataset.wallpaper)document.querySelector('.mac-native').classList.toggle('night-desktop',button.dataset.wallpaper==='night');
if(button.hasAttribute('data-reset-desktop'))render();
if(!button.dataset.macMenu)document.getElementById('native-menu').hidden=true;
if(button.dataset.macMenu){const menu=document.getElementById('native-menu');const which=button.dataset.macMenu;const options={apple:[['about','关于这台 Mac'],['preferences','桌面与外观']],finder:[['writing','显示文稿'],['about','关于 Geo']],file:[['writing','打开文稿'],['projects','打开项目'],['note','新的一页 · 备忘录']],edit:[['search','查找文章']],view:[['writing','显示访达'],['preferences','桌面与外观']],go:[['writing','文稿'],['projects','项目'],['terminal','终端']],window:[['writing','访达'],['projects','Safari'],['note','备忘录'],['terminal','终端']],help:[['about','关于 Geo'],['note','欢迎说明']]};menu.innerHTML=options[which].map(([a,t])=>`<button data-menu-action="${a}">${t}</button>`).join('');menu.style.left=button.getBoundingClientRect().left+'px';menu.hidden=false;}
if(button.dataset.menuAction){const a=button.dataset.menuAction;document.getElementById('native-menu').hidden=true;if(a==='about')document.getElementById('about').showModal();else if(a==='search'){openNative('finder');document.getElementById('finder-search').focus();}else openNative({writing:'finder',projects:'safari',note:'note'}[a]||a);}
});
document.addEventListener('submit',event=>{if(event.target.id!=='native-terminal-form')return;event.preventDefault();const input=document.getElementById('terminal-input');const command=input.value.trim().toLowerCase();const output=document.getElementById('terminal-output');const commands={help:'可用命令：whoami · ls · blog · projects · clear',whoami:'Geo Qiao — 分析师，写作者，喜欢折腾小工具。',ls:'Documents/    Projects/    Notes/'};if(command==='clear'){output.textContent='';}else if(command==='blog'){openNative('finder');}else if(command==='projects'){openNative('safari');}else{output.textContent=commands[command]||'输入 help 查看可用命令。';}input.value='';});
